/*
 * Built for Kinetic from scratch after the public preview of BoardUI's "AI Chat" (boardui.com/templates/ai-chat).
 * No BoardUI source was used.
 */
"use client";

import { useEffect, useRef, useState } from "react";
import { RiAddLine, RiCheckLine, RiFileCopyLine, RiPlayLine, RiRobot2Line } from "@remixicon/react";

import { useReducedMotion } from "@/hooks/use-reduced-motion";
import { cx } from "@/lib/cx";
import { Button } from "@/components/motion/button";
import { useCopyToClipboard } from "@/components/motion/code-block-copy";
import { Modal, ModalBody, ModalFooter, ModalHeader } from "@/components/motion/modal";
import { SettingsModal } from "@/components/motion/settings-modal";
import { Switch } from "@/components/motion/switch";
import {
  AI_CHAT_FILES,
  AI_CHAT_FOLDERS,
  AI_CHAT_INITIAL_STEPS,
  AI_CHAT_THREADS,
  fileFor,
  replyFor,
  stepsFor,
  type AiChatFile,
  type AiChatFolder,
  type AiChatMode,
  type AiChatThread,
  type AiChatView,
} from "@/components/motion/ai-chat-data";
import { AiChatChanges } from "@/components/motion/ai-chat-changes";
import { AiChatSidebar } from "@/components/motion/ai-chat-sidebar";
import { AiChatThreadView, CONTEXT_LIMIT, STEP_MS, type AiChatRun } from "@/components/motion/ai-chat-thread";

/** Pause with no steps (Ask mode) before the reply starts. */
const THINK_MS = 1100;
/** Hold on the finished checklist before the reply streams in. */
const DONE_HOLD_MS = 600;
/** Characters added per streaming tick, and the tick length. */
const CHUNK = 3;
const TICK_MS = 24;

export interface AiChatProps {
  folders?: AiChatFolder[];
  threads?: AiChatThread[];
  files?: AiChatFile[];
  /** Chat open on first render. */
  defaultThreadId?: string;
  /** Run the opening chat's last message through the agent on mount. */
  autoStart?: boolean;
  className?: string;
}

interface Automation {
  id: string;
  name: string;
  schedule: string;
  enabled: boolean;
  lastRun: string;
}

const AUTOMATIONS: Automation[] = [
  { id: "deps", name: "Bump patch dependencies", schedule: "Mondays 09:00", enabled: true, lastRun: "3d ago" },
  { id: "lint", name: "Lint and fix on push", schedule: "On every push to dev", enabled: true, lastRun: "2h ago" },
  { id: "notes", name: "Draft release notes", schedule: "Fridays 16:00", enabled: false, lastRun: "1w ago" },
];

export function AiChat({
  folders = AI_CHAT_FOLDERS,
  threads: initialThreads = AI_CHAT_THREADS,
  files: initialFiles = AI_CHAT_FILES,
  defaultThreadId = "coding",
  autoStart = true,
  className,
}: AiChatProps) {
  const reduced = useReducedMotion();
  const [threads, setThreads] = useState(initialThreads);
  const [activeId, setActiveId] = useState<string | null>(defaultThreadId);
  const [view, setView] = useState<AiChatView>("chat");
  const [collapsed, setCollapsed] = useState(false);
  const [files, setFiles] = useState(initialFiles);
  const [lastCommit, setLastCommit] = useState<string | null>(null);
  const [terminal, setTerminal] = useState<string[]>([]);
  const [panelOpen, setPanelOpen] = useState(true);
  const [wide, setWide] = useState(false);
  const [mode, setMode] = useState<AiChatMode>("agent");
  const [branch, setBranch] = useState("Main");
  const [project, setProject] = useState("project-sea");
  const [contextUsed, setContextUsed] = useState(114_000);
  const [planName, setPlanName] = useState("Pro Plan");
  const [modal, setModal] = useState<"settings" | "support" | "upgrade" | null>(null);
  const [automations, setAutomations] = useState(AUTOMATIONS);
  const [autoLint, setAutoLint] = useState(true);
  const [autoPanel, setAutoPanel] = useState(true);
  const [rules, setRules] = useState("Use kit tokens only. Keep components under 300 lines. Run lint before a build.");
  const [rulesSaved, setRulesSaved] = useState(true);
  const counter = useRef(1);
  const { copied, copy } = useCopyToClipboard(1600);

  // The opening chat arrives mid-run, the way the reference shows it.
  const [run, setRun] = useState<AiChatRun | null>(() => {
    const opening = initialThreads.find((th) => th.id === defaultThreadId);
    const prompt = opening?.turns.at(-1);
    if (!autoStart || !opening || prompt?.from !== "user") return null;
    return {
      id: 1,
      threadId: opening.id,
      steps: AI_CHAT_INITIAL_STEPS,
      step: 0,
      phase: "working",
      full: replyFor(prompt.text, "agent", 0),
      shown: "",
      prompt: prompt.text,
      mode: "agent",
    };
  });

  const active = threads.find((th) => th.id === activeId) ?? null;
  const log = (...lines: string[]) => setTerminal((t) => [...t, ...lines].slice(-200));
  const patchThread = (id: string, patch: (th: AiChatThread) => AiChatThread) =>
    setThreads((list) => list.map((th) => (th.id === id ? patch(th) : th)));

  const finish = (r: AiChatRun) => {
    patchThread(r.threadId, (th) => ({
      ...th,
      age: "now",
      turns: [...th.turns, { id: `a${r.id}`, from: "assistant", text: r.full, time: "now" }],
    }));
    if (r.mode === "agent") {
      setFiles((list) => [fileFor(r.prompt, r.id), ...list]);
      setLastCommit(null);
      if (autoLint) log("$ pnpm lint", "  0 problems", "$ pnpm build", "  Compiled successfully");
      if (autoPanel) setPanelOpen(true);
    }
    log(`run #${r.id} finished`);
    setContextUsed((u) => Math.min(CONTEXT_LIMIT, u + 2_400 + r.prompt.length * 30));
    setRun(null);
  };

  // #region critical
  // The agent timeline: one timer at a time walks the steps, holds on the
  // finished checklist, then streams the reply a few characters per tick.
  // Every state change re-arms the effect, and cleanup clears the old timer,
  // so stopping, deleting or unmounting never leaves a callback behind.
  useEffect(() => {
    if (!run) return;
    let timer: ReturnType<typeof setTimeout>;
    if (run.phase === "working") {
      const total = run.steps.length;
      const done = run.step >= total;
      timer = setTimeout(
        () => {
          if (done) {
            setRun({ ...run, phase: "streaming" });
            return;
          }
          log(`✓ ${run.steps[run.step] ?? ""}`);
          setRun({ ...run, step: run.step + 1 });
        },
        total === 0 ? THINK_MS : done ? DONE_HOLD_MS : STEP_MS,
      );
    } else {
      timer = setTimeout(
        () => {
          const shown = reduced ? run.full : run.full.slice(0, run.shown.length + CHUNK);
          if (shown.length >= run.full.length) finish(run);
          else setRun({ ...run, shown });
        },
        reduced ? 0 : TICK_MS,
      );
    }
    return () => clearTimeout(timer);
    // finish/log only call state setters, so the run and motion setting are the real inputs.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [run, reduced]);
  // #endregion

  const start = (threadId: string, prompt: string) => {
    counter.current += 1;
    const id = counter.current;
    const steps = stepsFor(prompt, mode).filter((s) => autoLint || !/lint/i.test(s));
    log(`$ agent run #${id} --mode ${mode} --branch ${branch}`);
    setRun({ id, threadId, steps, step: 0, phase: "working", full: replyFor(prompt, mode, id), shown: "", prompt, mode });
  };

  const send = (text: string) => {
    if (!active) return;
    counter.current += 1;
    const userTurn = { id: `u${counter.current}`, from: "user" as const, text, time: "now" };
    patchThread(active.id, (th) => ({
      ...th,
      age: "now",
      title: th.turns.length === 0 ? text.split("\n")[0]!.slice(0, 32) : th.title,
      turns: [...th.turns, userTurn],
    }));
    start(active.id, text);
  };

  const stop = () => {
    if (!run) return;
    const text = run.shown ? `${run.shown}… (stopped)` : `Stopped after ${run.step} of ${run.steps.length} steps.`;
    patchThread(run.threadId, (th) => ({ ...th, turns: [...th.turns, { id: `a${run.id}`, from: "assistant", text, time: "now" }] }));
    log(`run #${run.id} stopped`);
    setRun(null);
  };

  const regenerate = () => {
    if (!active || run) return;
    const lastUser = [...active.turns].reverse().find((t) => t.from === "user");
    if (!lastUser) return;
    patchThread(active.id, (th) => ({ ...th, turns: th.turns.slice(0, th.turns.lastIndexOf(lastUser) + 1) }));
    start(active.id, lastUser.text);
  };

  const newAgent = (folderId?: string) => {
    counter.current += 1;
    const id = `new-${counter.current}`;
    const folder = folderId ?? active?.folderId ?? folders[0]?.id ?? "default";
    setThreads((list) => [{ id, title: "New agent", folderId: folder, age: "now", turns: [] }, ...list]);
    setActiveId(id);
    setView("chat");
  };

  const remove = (id: string) => {
    const rest = threads.filter((th) => th.id !== id);
    setThreads(rest);
    if (run?.threadId === id) setRun(null);
    if (activeId === id) setActiveId(rest[0]?.id ?? null);
  };

  const commit = (message: string) => {
    log(`$ git commit -m "${message}"`, `[${branch}] ${files.length} files changed`);
    setLastCommit(`Committed "${message}" to ${branch}.`);
    setFiles([]);
  };

  const folderName = (id: string) => folders.find((f) => f.id === id)?.name ?? id;

  return (
    <div className={cx("flex h-full w-full gap-2 overflow-hidden bg-background-primary-default p-2", className)}>
      <AiChatSidebar
        folders={folders}
        threads={threads}
        activeThreadId={activeId}
        view={view}
        runningThreadId={run?.threadId ?? null}
        collapsed={collapsed}
        onCollapsedChange={setCollapsed}
        onSelectThread={(id) => {
          setActiveId(id);
          setView("chat");
        }}
        onNewAgent={newAgent}
        onView={setView}
        onOpenSettings={() => setModal("settings")}
        onOpenSupport={() => setModal("support")}
        onUpgrade={() => setModal("upgrade")}
        planName={planName}
      />

      {view === "chat" && active ? (
        <AiChatThreadView
          key={active.id}
          thread={active}
          folderName={folderName(active.folderId)}
          run={run?.threadId === active.id ? run : null}
          busyElsewhere={run !== null && run.threadId !== active.id}
          onSend={send}
          onStop={stop}
          onRegenerate={regenerate}
          onRename={(title) => patchThread(active.id, (th) => ({ ...th, title }))}
          onTogglePin={() => patchThread(active.id, (th) => ({ ...th, pinned: !th.pinned }))}
          onDelete={() => remove(active.id)}
          mode={mode}
          onModeChange={setMode}
          branch={branch}
          onBranchChange={setBranch}
          project={project}
          onProjectChange={setProject}
          contextUsed={contextUsed}
          panelOpen={panelOpen}
          onShowPanel={() => setPanelOpen(true)}
        />
      ) : view === "chat" ? (
        <section aria-label="No chat" className="flex flex-1 flex-col items-center justify-center gap-3 rounded-2xl bg-background-secondary-default">
          <p className="text-headline-semibold text-text-primary">No chats left</p>
          <Button variant="primary" size="small" leadingIcon={RiAddLine} onClick={() => newAgent()}>
            New agent
          </Button>
        </section>
      ) : (
        <section
          aria-label={view === "automations" ? "Automations" : "Customize"}
          className="flex min-w-0 flex-1 flex-col overflow-y-auto rounded-2xl bg-background-secondary-default p-6"
        >
          {view === "automations" ? (
            <div className="mx-auto flex w-full max-w-[560px] flex-col gap-4">
              <div className="flex items-center gap-3">
                <div className="flex-1">
                  <h2 className="text-title-3-semibold text-text-primary">Automations</h2>
                  <p className="text-body-2-regular text-text-secondary">Agents that run on a schedule or on repository events.</p>
                </div>
                <Button
                  size="small"
                  variant="secondary"
                  leadingIcon={RiAddLine}
                  onClick={() =>
                    setAutomations((list) => [
                      ...list,
                      { id: `auto-${list.length + 1}`, name: `Untitled automation ${list.length + 1}`, schedule: "Daily 08:00", enabled: false, lastRun: "never" },
                    ])
                  }
                >
                  New automation
                </Button>
              </div>
              <ul className="flex flex-col gap-2">
                {automations.map((a) => (
                  <li key={a.id} className="flex items-center gap-3 rounded-xl border border-separator-border bg-background-primary-default p-3 shadow-xs">
                    <span className="grid size-8 place-items-center rounded-lg bg-status-blue-background text-status-blue-text">
                      <RiRobot2Line aria-hidden className="size-4" />
                    </span>
                    <span className="flex min-w-0 flex-1 flex-col">
                      <span className="truncate text-body-2-semibold text-text-primary">{a.name}</span>
                      <span className="truncate text-caption-1-regular text-text-tertiary">
                        {a.schedule} · last run {a.lastRun}
                      </span>
                    </span>
                    <Button
                      size="xs"
                      variant="ghost"
                      leadingIcon={RiPlayLine}
                      onClick={() => {
                        log(`$ automation "${a.name}"`, "  done in 4s");
                        setAutomations((list) => list.map((x) => (x.id === a.id ? { ...x, lastRun: "just now" } : x)));
                      }}
                    >
                      Run now
                    </Button>
                    <Switch
                      aria-label={`Enable ${a.name}`}
                      isSelected={a.enabled}
                      onChange={(on) => setAutomations((list) => list.map((x) => (x.id === a.id ? { ...x, enabled: on } : x)))}
                    />
                  </li>
                ))}
              </ul>
            </div>
          ) : (
            <div className="mx-auto flex w-full max-w-[560px] flex-col gap-4">
              <div>
                <h2 className="text-title-3-semibold text-text-primary">Customize</h2>
                <p className="text-body-2-regular text-text-secondary">Rules and defaults every agent in this workspace follows.</p>
              </div>
              <label className="flex flex-col gap-1.5">
                <span className="text-caption-1-semibold text-text-secondary">Project rules</span>
                <textarea
                  value={rules}
                  rows={4}
                  onChange={(e) => {
                    setRules(e.target.value);
                    setRulesSaved(false);
                  }}
                  className="resize-none rounded-xl border border-border-button-default bg-background-primary-default p-3 text-body-2-regular text-text-primary outline-none focus:ring-2 focus:ring-border-focus-ring"
                />
              </label>
              <div className="flex items-center gap-2">
                <Button size="small" variant="primary" onClick={() => setRulesSaved(true)}>
                  Save rules
                </Button>
                <span aria-live="polite" className="text-caption-1-medium text-text-tertiary">
                  {rulesSaved ? "Saved" : "Unsaved changes"}
                </span>
              </div>
              <div className="flex flex-col gap-3 rounded-xl border border-separator-border bg-background-primary-default p-4">
                <Switch isSelected={autoLint} onChange={setAutoLint}>
                  <span className="text-body-2-medium text-text-primary">Run lint and a production build after edits</span>
                </Switch>
                <Switch isSelected={autoPanel} onChange={setAutoPanel}>
                  <span className="text-body-2-medium text-text-primary">Open the changes panel when a run ends</span>
                </Switch>
              </div>
            </div>
          )}
        </section>
      )}

      {panelOpen && (
        <AiChatChanges
          files={files}
          onDiscardAll={() => {
            log(`$ git restore . (${files.length} files)`);
            setFiles([]);
          }}
          onRevertFile={(id) => setFiles((list) => list.filter((f) => f.id !== id))}
          onCommit={commit}
          branch={branch}
          lastCommit={lastCommit}
          terminal={terminal}
          onClearTerminal={() => setTerminal([])}
          wide={wide}
          onWideChange={setWide}
          onClose={() => setPanelOpen(false)}
        />
      )}

      <SettingsModal isOpen={modal === "settings"} onClose={() => setModal(null)} />

      <Modal isOpen={modal === "support"} onOpenChange={(o) => !o && setModal(null)} size="sm">
        <ModalHeader title="Support" description="We answer within one working day. Include the chat link if a run went wrong." />
        <ModalBody className="pb-2">
          <div className="flex items-center gap-2 rounded-xl bg-background-secondary-default p-3">
            <span className="flex-1 font-mono text-body-2-regular text-text-primary">help@vibl.dev</span>
            <Button size="xs" variant="secondary" leadingIcon={copied ? RiCheckLine : RiFileCopyLine} onClick={() => void copy("help@vibl.dev")}>
              {copied ? "Copied" : "Copy"}
            </Button>
          </div>
        </ModalBody>
        <ModalFooter>
          <Button variant="secondary" onClick={() => setModal(null)}>
            Close
          </Button>
        </ModalFooter>
      </Modal>

      <Modal isOpen={modal === "upgrade"} onOpenChange={(o) => !o && setModal(null)} size="sm">
        <ModalHeader title="Board team plan" description={`You are on the ${planName}.`} />
        <ModalBody className="flex flex-col gap-2 pb-2">
          {[
            { name: "Pro Plan", price: "$16 per seat", note: "Unlimited chats, 3 automations" },
            { name: "Team Plan", price: "$24 per seat", note: "Shared rules, unlimited automations, audit log" },
          ].map((p) => (
            <button
              key={p.name}
              type="button"
              aria-pressed={planName === p.name}
              onClick={() => {
                setPlanName(p.name);
                setModal(null);
              }}
              className={cx(
                "flex cursor-pointer items-center gap-3 rounded-xl border p-3 text-start outline-none focus-visible:ring-2 focus-visible:ring-border-focus-ring",
                planName === p.name ? "border-blue-500 bg-status-blue-background" : "border-separator-border hover:bg-background-secondary-default",
              )}
            >
              <span className="flex flex-1 flex-col">
                <span className="text-body-2-semibold text-text-primary">{p.name}</span>
                <span className="text-caption-1-regular text-text-tertiary">{p.note}</span>
              </span>
              <span className="text-caption-1-semibold text-text-secondary">{p.price}</span>
            </button>
          ))}
        </ModalBody>
        <ModalFooter>
          <Button variant="secondary" onClick={() => setModal(null)}>
            Close
          </Button>
        </ModalFooter>
      </Modal>
    </div>
  );
}

/*
 * Built for Kinetic from scratch after the public preview of BoardUI's "AI Chat" (boardui.com/templates/ai-chat).
 * No BoardUI source was used.
 */
import { useState } from "react";
import {
  RiAddLine,
  RiChat3Line,
  RiCheckLine,
  RiCustomerService2Line,
  RiExpandUpDownLine,
  RiFolderLine,
  RiFolderOpenLine,
  RiMagicLine,
  RiPushpinLine,
  RiRobot2Line,
  RiSearchLine,
  RiSettings3Line,
  RiSidebarFoldLine,
  RiSidebarUnfoldLine,
} from "@remixicon/react";

import { cx } from "@/lib/cx";
import { Button } from "@/components/motion/button";
import { CommandPaletteItem, CommandPaletteSection } from "@/components/motion/command-palette";
import { Dropdown, DropdownDivider, DropdownGroup, DropdownItem, DropdownPopover, DropdownTrigger } from "@/components/motion/dropdown";
import { QuickSearchButton } from "@/components/motion/quick-search-button";
import { ThemeToggle } from "@/components/motion/theme-toggle";
import { IconAction, type AiChatFolder, type AiChatThread, type AiChatView } from "@/components/motion/ai-chat-data";

const ACCOUNTS = [
  { id: "mira", name: "Mira Lindqvist", email: "mira@vibl.dev" },
  { id: "theo", name: "Theo Park", email: "theo@vibl.dev" },
];

export interface AiChatSidebarProps {
  folders: AiChatFolder[];
  threads: AiChatThread[];
  activeThreadId: string | null;
  view: AiChatView;
  /** Thread whose agent is working; its row shows a live dot instead of the age. */
  runningThreadId: string | null;
  collapsed: boolean;
  onCollapsedChange: (collapsed: boolean) => void;
  onSelectThread: (id: string) => void;
  onNewAgent: (folderId?: string) => void;
  onView: (view: AiChatView) => void;
  onOpenSettings: () => void;
  onOpenSupport: () => void;
  onUpgrade: () => void;
  planName: string;
}

const NAV_ROW = cx(
  "flex h-8 w-full cursor-pointer items-center gap-2 rounded-lg px-2 text-start text-body-2-medium text-text-secondary outline-none",
  "transition-colors duration-150 ease-out motion-reduce:transition-none",
  "hover:bg-background-tertiary-default hover:text-text-primary focus-visible:ring-2 focus-visible:ring-border-focus-ring",
);

export function AiChatSidebar({
  folders,
  threads,
  activeThreadId,
  view,
  runningThreadId,
  collapsed,
  onCollapsedChange,
  onSelectThread,
  onNewAgent,
  onView,
  onOpenSettings,
  onOpenSupport,
  onUpgrade,
  planName,
}: AiChatSidebarProps) {
  const [account, setAccount] = useState(ACCOUNTS[0]!);
  const [accountOpen, setAccountOpen] = useState(false);
  const [open, setOpen] = useState<Record<string, boolean>>({ vibl: true });
  // Opening a chat from search unfolds its repository (derived during render, not in an effect).
  const [seenActive, setSeenActive] = useState(activeThreadId);
  if (seenActive !== activeThreadId) {
    setSeenActive(activeThreadId);
    const folderId = threads.find((th) => th.id === activeThreadId)?.folderId;
    if (folderId && !open[folderId]) setOpen((o) => ({ ...o, [folderId]: true }));
  }

  const search = (
    <QuickSearchButton
      label="Quick Search"
      shortcutKey="l"
      placeholder="Search chats and actions"
      paletteLabel="Search chats"
      onAction={(key) => {
        const id = String(key);
        if (id === "action:new") onNewAgent();
        else if (id === "action:settings") onOpenSettings();
        else if (id === "action:automations") onView("automations");
        else onSelectThread(id);
      }}
      className="max-w-none bg-background-primary-default"
    >
      <CommandPaletteSection title="Actions">
        <CommandPaletteItem id="action:new" icon={RiAddLine}>New agent</CommandPaletteItem>
        <CommandPaletteItem id="action:automations" icon={RiRobot2Line}>Automations</CommandPaletteItem>
        <CommandPaletteItem id="action:settings" icon={RiSettings3Line}>Settings</CommandPaletteItem>
      </CommandPaletteSection>
      <CommandPaletteSection title="Chats">
        {threads.map((th) => (
          <CommandPaletteItem
            key={th.id}
            id={th.id}
            icon={RiChat3Line}
            textValue={`${th.title} ${folders.find((f) => f.id === th.folderId)?.name ?? ""}`}
            description={folders.find((f) => f.id === th.folderId)?.name}
          >
            {th.title}
          </CommandPaletteItem>
        ))}
      </CommandPaletteSection>
    </QuickSearchButton>
  );

  if (collapsed) {
    return (
      <nav
        aria-label="Agent sidebar"
        className="flex w-14 shrink-0 flex-col items-center gap-1 rounded-2xl border border-separator-border bg-background-secondary-default py-3 shadow-sidebar"
      >
        <IconAction label="Expand sidebar" icon={RiSidebarUnfoldLine} onPress={() => onCollapsedChange(false)} />
        <IconAction label="New agent" icon={RiAddLine} onPress={() => onNewAgent()} />
        <IconAction label="Automations" icon={RiRobot2Line} active={view === "automations"} onPress={() => onView("automations")} />
        <IconAction label="Customize" icon={RiMagicLine} active={view === "customize"} onPress={() => onView("customize")} />
        <IconAction label="Search chats" icon={RiSearchLine} onPress={() => onCollapsedChange(false)} tip="Expand to search" />
        <div className="mt-auto flex flex-col items-center gap-1">
          <ThemeToggle collapsed />
          <IconAction label="Settings" icon={RiSettings3Line} onPress={onOpenSettings} />
        </div>
      </nav>
    );
  }

  return (
    <nav
      aria-label="Agent sidebar"
      className="flex w-[248px] shrink-0 flex-col rounded-2xl border border-separator-border bg-background-secondary-default shadow-sidebar"
    >
      <div className="flex items-center gap-1 px-2.5 pt-2.5">
        <Dropdown isOpen={accountOpen} onOpenChange={setAccountOpen}>
          <DropdownTrigger
            aria-label={`Account: ${account.name}`}
            className="flex min-w-0 flex-1 cursor-pointer items-center gap-2 rounded-lg p-1 text-start outline-none hover:bg-background-tertiary-default data-[focus-visible]:ring-2 data-[focus-visible]:ring-border-focus-ring"
          >
            <span className="grid size-6 shrink-0 place-items-center rounded-full bg-background-tertiary-default text-caption-1-semibold text-text-secondary">
              {account.name[0]}
            </span>
            <span className="truncate text-body-2-semibold text-text-primary">{account.name}</span>
            <RiExpandUpDownLine aria-hidden className="size-3.5 shrink-0 text-foreground-icon-tertiary" />
          </DropdownTrigger>
          <DropdownPopover aria-label="Switch account" className="w-[240px]">
            <DropdownGroup label="Accounts">
              {ACCOUNTS.map((a) => (
                <DropdownItem
                  key={a.id}
                  selected={a.id === account.id}
                  onSelect={() => {
                    setAccount(a);
                    setAccountOpen(false);
                  }}
                >
                  <span className="grid size-5 place-items-center rounded-full bg-background-tertiary-default text-caption-2-semibold">{a.name[0]}</span>
                  <span className="flex min-w-0 flex-1 flex-col">
                    <span className="truncate text-body-2-medium text-text-primary">{a.name}</span>
                    <span className="truncate text-caption-1-regular text-text-tertiary">{a.email}</span>
                  </span>
                  {a.id === account.id && <RiCheckLine aria-hidden className="size-4 text-foreground-icon-primary" />}
                </DropdownItem>
              ))}
            </DropdownGroup>
            <DropdownDivider />
            <DropdownItem
              onSelect={() => {
                setAccountOpen(false);
                onOpenSettings();
              }}
            >
              <RiSettings3Line aria-hidden className="size-4 text-foreground-icon-secondary" />
              <span className="text-body-2-medium text-text-primary">Account settings</span>
            </DropdownItem>
          </DropdownPopover>
        </Dropdown>
        <IconAction label="Collapse sidebar" icon={RiSidebarFoldLine} onPress={() => onCollapsedChange(true)} />
      </div>

      <div className="px-2.5 pt-2.5">{search}</div>

      <div className="flex flex-col gap-0.5 px-2.5 pt-3">
        <button type="button" className={NAV_ROW} onClick={() => onNewAgent()}>
          <RiAddLine aria-hidden className="size-4 text-foreground-icon-secondary" />
          New agent
        </button>
        <button
          type="button"
          aria-current={view === "automations" ? "page" : undefined}
          className={cx(NAV_ROW, view === "automations" && "bg-background-tertiary-default text-text-primary")}
          onClick={() => onView("automations")}
        >
          <RiRobot2Line aria-hidden className="size-4 text-foreground-icon-secondary" />
          Automations
        </button>
        <button
          type="button"
          aria-current={view === "customize" ? "page" : undefined}
          className={cx(NAV_ROW, view === "customize" && "bg-background-tertiary-default text-text-primary")}
          onClick={() => onView("customize")}
        >
          <RiMagicLine aria-hidden className="size-4 text-foreground-icon-secondary" />
          Customize
        </button>
      </div>

      <div className="min-h-0 flex-1 overflow-y-auto px-2.5 pb-2 pt-4">
        <p className="px-2 pb-1.5 text-caption-1-medium text-text-tertiary">Repositories</p>
        <ul className="flex flex-col gap-0.5">
          {folders.map((folder) => {
            const isOpen = open[folder.id] ?? false;
            const chats = threads.filter((th) => th.folderId === folder.id);
            const FolderIcon = isOpen ? RiFolderOpenLine : RiFolderLine;
            return (
              <li key={folder.id}>
                <div className="group/folder flex items-center">
                  <button
                    type="button"
                    aria-expanded={isOpen}
                    className={cx(NAV_ROW, "min-w-0 flex-1")}
                    onClick={() => setOpen((o) => ({ ...o, [folder.id]: !isOpen }))}
                  >
                    <FolderIcon aria-hidden className="size-4 shrink-0 text-foreground-icon-secondary" />
                    <span className="truncate">{folder.name}</span>
                  </button>
                  <IconAction
                    label={`New chat in ${folder.name}`}
                    icon={RiAddLine}
                    onPress={() => onNewAgent(folder.id)}
                    className="size-6 opacity-0 group-hover/folder:opacity-100 data-[focus-visible]:opacity-100"
                  />
                </div>
                {isOpen && (
                  <ul className="ms-4 flex flex-col gap-0.5 border-s border-separator-border ps-2">
                    {chats.length === 0 && <li className="px-2 py-1 text-caption-1-regular text-text-tertiary">No chats yet</li>}
                    {chats.map((th) => {
                      const active = view === "chat" && th.id === activeThreadId;
                      const running = th.id === runningThreadId;
                      return (
                        <li key={th.id}>
                          <button
                            type="button"
                            aria-current={active ? "page" : undefined}
                            onClick={() => onSelectThread(th.id)}
                            className={cx(
                              NAV_ROW,
                              "h-7 text-caption-1-medium",
                              active && "bg-background-tertiary-default text-text-primary",
                            )}
                          >
                            {th.pinned && <RiPushpinLine aria-label="Pinned" className="size-3 shrink-0 text-foreground-icon-tertiary" />}
                            <span className="min-w-0 flex-1 truncate">{th.title}</span>
                            {running ? (
                              <span className="flex items-center gap-1 text-caption-2-medium text-status-blue-text">
                                <span className="size-1.5 animate-pulse rounded-full bg-blue-500 motion-reduce:animate-none" aria-hidden />
                                working
                              </span>
                            ) : (
                              <span className="rounded-md bg-background-tertiary-default px-1.5 py-px text-caption-2-medium text-text-tertiary">
                                {th.age}
                              </span>
                            )}
                          </button>
                        </li>
                      );
                    })}
                  </ul>
                )}
              </li>
            );
          })}
        </ul>
      </div>

      <div className="flex flex-col gap-0.5 px-2.5 pb-2.5">
        <ThemeToggle appearance="sidebar-segmented" className="mb-2 self-start" />
        <button type="button" className={NAV_ROW} onClick={onOpenSupport}>
          <RiCustomerService2Line aria-hidden className="size-4 text-foreground-icon-secondary" />
          Support
        </button>
        <button type="button" className={NAV_ROW} onClick={onOpenSettings}>
          <RiSettings3Line aria-hidden className="size-4 text-foreground-icon-secondary" />
          Settings
        </button>
        <div className="mt-2 flex items-center gap-2 rounded-xl border border-separator-border bg-background-primary-default p-2 shadow-xs">
          <span className="grid size-7 shrink-0 place-items-center rounded-full bg-blue-500 text-caption-1-semibold text-text-white">B</span>
          <span className="flex min-w-0 flex-1 flex-col">
            <span className="truncate text-caption-1-semibold text-text-primary">Board team</span>
            <span className="truncate text-caption-2-regular text-text-tertiary">{planName}</span>
          </span>
          <Button size="xs" variant="secondary" onClick={onUpgrade}>
            {planName === "Pro Plan" ? "Upgrade" : "Manage"}
          </Button>
        </div>
      </div>
    </nav>
  );
}

/*
 * Built for Kinetic from scratch after the public preview of BoardUI's "AI Chat" (boardui.com/templates/ai-chat).
 * No BoardUI source was used.
 */
import { useEffect, useRef, useState, type ComponentType, type KeyboardEvent } from "react";
import {
  RiAddLine,
  RiArrowDownSLine,
  RiArrowRightSLine,
  RiArrowUpLine,
  RiAtLine,
  RiAttachmentLine,
  RiChat3Line,
  RiCheckLine,
  RiCloseLine,
  RiDeleteBinLine,
  RiEditLine,
  RiFlowChart,
  RiFolderLine,
  RiGitBranchLine,
  RiInfinityLine,
  RiLayoutRightLine,
  RiMicFill,
  RiMicLine,
  RiMoreLine,
  RiPushpinLine,
  RiSparkling2Line,
  RiStopFill,
  RiUnpinLine,
  RiUpload2Line,
} from "@remixicon/react";

import { useReducedMotion } from "@/hooks/use-reduced-motion";
import { cx } from "@/lib/cx";
import { AgentProgress } from "@/components/motion/agent-progress";
import { AgentThinking } from "@/components/motion/agent-thinking";
import { AlertDialog } from "@/components/motion/modal";
import { ChatMessageBubble } from "@/components/motion/chat-message-bubble";
import { useCopyToClipboard } from "@/components/motion/code-block-copy";
import { ContextUsageRing } from "@/components/motion/context-usage-ring";
import { Dropdown, DropdownGroup, DropdownItem, DropdownPopover, DropdownTrigger } from "@/components/motion/dropdown";
import { ModelSelect } from "@/components/motion/model-select";
import { IconAction, type AiChatMode, type AiChatThread } from "@/components/motion/ai-chat-data";

/** A live agent run, owned by the shell so it survives switching chats. */
export interface AiChatRun {
  id: number;
  threadId: string;
  steps: string[];
  /** Index of the step in progress; equals steps.length once all are done. */
  step: number;
  phase: "working" | "streaming";
  full: string;
  shown: string;
  prompt: string;
  mode: AiChatMode;
}

export const CONTEXT_LIMIT = 200_000;

type IconComponent = ComponentType<{ className?: string; "aria-hidden"?: boolean | "true" | "false" }>;

const MODES: { id: AiChatMode; label: string; hint: string; icon: IconComponent }[] = [
  { id: "agent", label: "Agent", hint: "Plans, edits files and runs checks", icon: RiInfinityLine },
  { id: "ask", label: "Ask", hint: "Answers without touching files", icon: RiChat3Line },
  { id: "plan", label: "Plan", hint: "Writes a plan for you to approve", icon: RiFlowChart },
];
const BRANCHES = ["Main", "dev", "feat/dark-tokens"];
const PROJECTS = ["project-sea", "boardui", "strider-site"];
const SUGGESTIONS = [
  "Add a loading skeleton to the dashboard cards",
  "Refactor the dropdown into smaller parts",
  "Run lint and a production build",
];
const DICTATION = "and add a short changelog entry when you're done";

/** Small text dropdown used by the status bar under the composer. */
function StatusMenu<T extends string>({
  label,
  icon: Icon,
  value,
  display,
  options,
  onChange,
}: {
  label: string;
  icon: IconComponent;
  value: T;
  display: string;
  options: { id: T; label: string; hint?: string }[];
  onChange: (id: T) => void;
}) {
  const [open, setOpen] = useState(false);
  return (
    <Dropdown isOpen={open} onOpenChange={setOpen}>
      <DropdownTrigger
        aria-label={`${label}: ${display}`}
        className="inline-flex h-6 cursor-pointer items-center gap-1 rounded-md px-1.5 text-caption-1-medium text-text-secondary outline-none hover:bg-background-tertiary-default hover:text-text-primary data-[focus-visible]:ring-2 data-[focus-visible]:ring-border-focus-ring"
      >
        <Icon aria-hidden className="size-3.5 text-foreground-icon-secondary" />
        {display}
        <RiArrowDownSLine aria-hidden className="size-3.5 text-foreground-icon-tertiary" />
      </DropdownTrigger>
      <DropdownPopover aria-label={label} placement="top start" className="w-[220px]">
        <DropdownGroup label={label}>
          {options.map((o) => (
            <DropdownItem
              key={o.id}
              selected={o.id === value}
              className="px-2 py-1.5"
              onSelect={() => {
                onChange(o.id);
                setOpen(false);
              }}
            >
              <span className="flex min-w-0 flex-1 flex-col">
                <span className="text-body-2-medium text-text-primary">{o.label}</span>
                {o.hint && <span className="text-caption-1-regular text-text-tertiary">{o.hint}</span>}
              </span>
              {o.id === value && <RiCheckLine aria-hidden className="size-4 text-foreground-icon-primary" />}
            </DropdownItem>
          ))}
        </DropdownGroup>
      </DropdownPopover>
    </Dropdown>
  );
}

export interface AiChatThreadProps {
  thread: AiChatThread;
  folderName: string;
  /** The run for this thread, if one is live. */
  run: AiChatRun | null;
  /** Another chat's agent is busy; sending here is blocked until it ends. */
  busyElsewhere: boolean;
  onSend: (text: string) => void;
  onStop: () => void;
  onRegenerate: () => void;
  onRename: (title: string) => void;
  onTogglePin: () => void;
  onDelete: () => void;
  mode: AiChatMode;
  onModeChange: (mode: AiChatMode) => void;
  branch: string;
  onBranchChange: (branch: string) => void;
  project: string;
  onProjectChange: (project: string) => void;
  contextUsed: number;
  panelOpen: boolean;
  onShowPanel: () => void;
}

export function AiChatThreadView({
  thread,
  folderName,
  run,
  busyElsewhere,
  onSend,
  onStop,
  onRegenerate,
  onRename,
  onTogglePin,
  onDelete,
  mode,
  onModeChange,
  branch,
  onBranchChange,
  project,
  onProjectChange,
  contextUsed,
  panelOpen,
  onShowPanel,
}: AiChatThreadProps) {
  const reduced = useReducedMotion();
  const [draft, setDraft] = useState("");
  const [attachments, setAttachments] = useState<string[]>([]);
  const [listening, setListening] = useState(false);
  const [renaming, setRenaming] = useState(false);
  const [moreOpen, setMoreOpen] = useState(false);
  const [attachOpen, setAttachOpen] = useState(false);
  const [confirmDelete, setConfirmDelete] = useState(false);
  const { copied, copy } = useCopyToClipboard(1600);
  const inputRef = useRef<HTMLTextAreaElement>(null);
  const scrollRef = useRef<HTMLDivElement>(null);

  // Dictation stand-in: listening ends after a moment and drops a phrase into the field.
  useEffect(() => {
    if (!listening) return;
    const timer = setTimeout(() => {
      setDraft((d) => (d ? `${d.trimEnd()} ${DICTATION}` : DICTATION));
      setListening(false);
    }, 2200);
    return () => clearTimeout(timer);
  }, [listening]);

  // Grow the field with its content up to five lines.
  useEffect(() => {
    const el = inputRef.current;
    if (!el) return;
    el.style.height = "auto";
    el.style.height = `${Math.min(el.scrollHeight, 120)}px`;
  }, [draft]);

  // Keep the newest turn in view while the reply streams in.
  const streamLength = run?.shown.length ?? 0;
  useEffect(() => {
    const el = scrollRef.current;
    if (el) el.scrollTop = el.scrollHeight;
  }, [thread.turns.length, streamLength, run?.step]);

  const running = run !== null;
  const send = () => {
    const text = draft.trim();
    if (!text || running || busyElsewhere) {
      inputRef.current?.focus();
      return;
    }
    const withFiles = attachments.length ? `${text}\n\nAttached: ${attachments.map((a) => `\`${a}\``).join(", ")}` : text;
    onSend(withFiles);
    setDraft("");
    setAttachments([]);
  };
  const onKeyDown = (e: KeyboardEvent<HTMLTextAreaElement>) => {
    if (e.key === "Enter" && !e.shiftKey && !e.nativeEvent.isComposing) {
      e.preventDefault();
      send();
    }
  };
  const attach = (name: string) => {
    setAttachments((a) => (a.includes(name) ? a : [...a, name]));
    setAttachOpen(false);
    inputRef.current?.focus();
  };

  const lastAssistant = [...thread.turns].reverse().find((turn) => turn.from === "assistant");
  const ModeIcon = MODES.find((m) => m.id === mode)?.icon ?? RiInfinityLine;

  return (
    <section aria-label={`Chat: ${thread.title}`} className="flex min-w-0 flex-1 flex-col rounded-2xl bg-background-secondary-default">
      <header className="flex h-12 shrink-0 items-center gap-1 px-3">
        <RiFolderLine aria-hidden className="size-4 shrink-0 text-foreground-icon-tertiary" />
        <span className="truncate text-caption-1-medium text-text-tertiary">{folderName}</span>
        <RiArrowRightSLine aria-hidden className="size-3.5 shrink-0 text-foreground-icon-tertiary" />
        {renaming ? (
          <input
            aria-label="Chat title"
            defaultValue={thread.title}
            autoFocus
            className="h-7 min-w-0 flex-1 rounded-md border border-border-button-default bg-background-primary-default px-2 text-caption-1-medium text-text-primary outline-none focus:ring-2 focus:ring-border-focus-ring"
            onBlur={(e) => {
              const v = e.currentTarget.value.trim();
              if (v) onRename(v);
              setRenaming(false);
            }}
            onKeyDown={(e) => {
              if (e.key === "Enter") e.currentTarget.blur();
              if (e.key === "Escape") setRenaming(false);
            }}
          />
        ) : (
          <h2 className="min-w-0 flex-1 truncate text-caption-1-semibold text-text-primary">{thread.title}</h2>
        )}
        <IconAction
          label={copied ? "Link copied" : "Copy share link"}
          icon={copied ? RiCheckLine : RiUpload2Line}
          onPress={() => void copy(`https://vibl.dev/share/${thread.id}`)}
        />
        <Dropdown isOpen={moreOpen} onOpenChange={setMoreOpen}>
          <DropdownTrigger
            aria-label="Chat options"
            className="grid size-7 cursor-pointer place-items-center rounded-lg text-foreground-icon-secondary outline-none hover:bg-background-tertiary-default data-[focus-visible]:ring-2 data-[focus-visible]:ring-border-focus-ring"
          >
            <RiMoreLine aria-hidden className="size-4" />
          </DropdownTrigger>
          <DropdownPopover aria-label="Chat options" placement="bottom end" className="w-[200px]">
            <DropdownItem
              className="px-2 py-1.5"
              onSelect={() => {
                setMoreOpen(false);
                setRenaming(true);
              }}
            >
              <RiEditLine aria-hidden className="size-4 text-foreground-icon-secondary" />
              <span className="text-body-2-medium text-text-primary">Rename</span>
            </DropdownItem>
            <DropdownItem
              className="px-2 py-1.5"
              onSelect={() => {
                setMoreOpen(false);
                onTogglePin();
              }}
            >
              {thread.pinned ? (
                <RiUnpinLine aria-hidden className="size-4 text-foreground-icon-secondary" />
              ) : (
                <RiPushpinLine aria-hidden className="size-4 text-foreground-icon-secondary" />
              )}
              <span className="text-body-2-medium text-text-primary">{thread.pinned ? "Unpin" : "Pin"}</span>
            </DropdownItem>
            <DropdownItem
              className="px-2 py-1.5"
              onSelect={() => {
                setMoreOpen(false);
                setConfirmDelete(true);
              }}
            >
              <RiDeleteBinLine aria-hidden className="size-4 text-text-destructive" />
              <span className="text-body-2-medium text-text-destructive">Delete chat</span>
            </DropdownItem>
          </DropdownPopover>
        </Dropdown>
        {!panelOpen && <IconAction label="Show changes panel" icon={RiLayoutRightLine} onPress={onShowPanel} />}
      </header>

      <div ref={scrollRef} className="min-h-0 flex-1 overflow-y-auto px-4 pb-4">
        {thread.turns.length === 0 && !run ? (
          <div className="mx-auto flex h-full max-w-sm flex-col items-center justify-center gap-3 text-center">
            <span className="grid size-10 place-items-center rounded-full bg-background-primary-default shadow-xs">
              <RiSparkling2Line aria-hidden className="size-5 text-foreground-icon-secondary" />
            </span>
            <p className="text-headline-semibold text-text-primary">What should the agent build?</p>
            <p className="text-body-2-regular text-text-secondary">It works in {folderName} on the {branch} branch.</p>
            <div className="mt-1 flex flex-col gap-1.5">
              {SUGGESTIONS.map((s) => (
                <button
                  key={s}
                  type="button"
                  onClick={() => {
                    setDraft(s);
                    inputRef.current?.focus();
                  }}
                  className="cursor-pointer rounded-full border border-separator-border bg-background-primary-default px-3 py-1.5 text-caption-1-medium text-text-secondary outline-none transition-colors duration-150 ease-out hover:text-text-primary focus-visible:ring-2 focus-visible:ring-border-focus-ring motion-reduce:transition-none"
                >
                  {s}
                </button>
              ))}
            </div>
          </div>
        ) : (
          <ol className="mx-auto flex max-w-[640px] flex-col gap-4 pt-2" aria-label="Messages">
            {thread.turns.map((turn) => (
              <li key={turn.id}>
                <ChatMessageBubble
                  from={turn.from}
                  text={turn.text}
                  time={turn.time}
                  name={turn.from === "user" ? "You" : "Agent"}
                  onRegenerate={turn.id === lastAssistant?.id && !running ? onRegenerate : undefined}
                />
              </li>
            ))}
            {run && run.phase === "working" && (
              <li className="flex flex-col gap-2" aria-live="polite">
                {run.steps.length > 0 && (
                  <AgentProgress key={run.id} steps={run.steps} step={run.step} stepDuration={STEP_MS} className="max-w-[320px]" />
                )}
                <AgentThinking variant="infinity" label="Thinking" showTimer shimmer={!reduced} />
              </li>
            )}
            {run && run.phase === "streaming" && (
              <li aria-live="polite" aria-busy="true">
                <ChatMessageBubble from="assistant" name="Agent" text={run.shown || "…"} />
              </li>
            )}
          </ol>
        )}
      </div>

      <div className="shrink-0 px-3 pb-2">
        <div className="group/composer relative mx-auto max-w-[680px]">
          <div
            aria-hidden
            className={cx(
              "pointer-events-none absolute -inset-1 rounded-[28px] bg-linear-to-r from-status-blue-text via-status-purple-text to-status-cyan-text opacity-0 blur-md",
              "transition-opacity duration-300 ease-out group-focus-within/composer:opacity-30 motion-reduce:transition-none",
              running && "animate-pulse opacity-40 motion-reduce:animate-none",
            )}
          />
          <div className="relative flex flex-col rounded-3xl border border-separator-border bg-background-primary-default shadow-sm">
            {attachments.length > 0 && (
              <ul aria-label="Attachments" className="flex flex-wrap gap-1 px-3 pt-2">
                {attachments.map((a) => (
                  <li key={a} className="flex items-center gap-1 rounded-md bg-background-tertiary-default py-0.5 pe-0.5 ps-2 text-caption-1-medium text-text-secondary">
                    {a}
                    <button
                      type="button"
                      aria-label={`Remove ${a}`}
                      onClick={() => setAttachments((list) => list.filter((x) => x !== a))}
                      className="grid size-4 cursor-pointer place-items-center rounded text-foreground-icon-tertiary outline-none hover:text-foreground-icon-primary focus-visible:ring-2 focus-visible:ring-border-focus-ring"
                    >
                      <RiCloseLine aria-hidden className="size-3" />
                    </button>
                  </li>
                ))}
              </ul>
            )}
            <div className="flex items-end gap-1.5 p-1.5">
              <Dropdown isOpen={attachOpen} onOpenChange={setAttachOpen}>
                <DropdownTrigger
                  aria-label="Add context"
                  className="grid size-8 shrink-0 cursor-pointer place-items-center rounded-full bg-ai-chat-composer-add-background text-foreground-icon-primary outline-none hover:bg-ai-chat-composer-add-hover-background data-[focus-visible]:ring-2 data-[focus-visible]:ring-border-focus-ring"
                >
                  <RiAddLine aria-hidden className="size-4" />
                </DropdownTrigger>
                <DropdownPopover aria-label="Add context" placement="top start" className="w-[220px]">
                  <DropdownItem className="px-2 py-1.5" onSelect={() => attach("design-notes.md")}>
                    <RiAttachmentLine aria-hidden className="size-4 text-foreground-icon-secondary" />
                    <span className="text-body-2-medium text-text-primary">Attach design-notes.md</span>
                  </DropdownItem>
                  <DropdownItem className="px-2 py-1.5" onSelect={() => attach("@button.tsx")}>
                    <RiAtLine aria-hidden className="size-4 text-foreground-icon-secondary" />
                    <span className="text-body-2-medium text-text-primary">Mention button.tsx</span>
                  </DropdownItem>
                  <DropdownItem className="px-2 py-1.5" onSelect={() => attach("@uncommitted-changes")}>
                    <RiGitBranchLine aria-hidden className="size-4 text-foreground-icon-secondary" />
                    <span className="text-body-2-medium text-text-primary">Uncommitted changes</span>
                  </DropdownItem>
                </DropdownPopover>
              </Dropdown>
              <textarea
                ref={inputRef}
                rows={1}
                value={draft}
                onChange={(e) => setDraft(e.target.value)}
                onKeyDown={onKeyDown}
                aria-label="Message the agent"
                placeholder={listening ? "Listening…" : busyElsewhere ? "Another chat's agent is working…" : "Ask me anything"}
                className="max-h-[120px] min-h-8 min-w-0 flex-1 resize-none bg-transparent px-1 py-1.5 text-body-2-regular text-text-primary outline-none placeholder:text-text-placeholder"
              />
              <ModelSelect variant="ghost" size="sm" aria-label="Model" defaultValue="swift-2" className="shrink-0" />
              <IconAction
                label={listening ? "Stop dictation" : "Dictate"}
                icon={listening ? RiMicFill : RiMicLine}
                active={listening}
                onPress={() => setListening((l) => !l)}
                className={cx("size-8 rounded-full", listening && "text-status-rose-text")}
              />
              <button
                type="button"
                aria-label={running ? "Stop the agent" : "Send message"}
                onClick={running ? onStop : send}
                className={cx(
                  "grid size-8 shrink-0 cursor-pointer place-items-center rounded-full bg-blue-500 text-text-white outline-none",
                  "transition-[opacity,scale] duration-150 ease-out active:scale-95 focus-visible:ring-2 focus-visible:ring-border-focus-ring motion-reduce:transition-none motion-reduce:active:scale-100",
                  !running && (!draft.trim() || busyElsewhere) && "opacity-50",
                )}
              >
                {running ? <RiStopFill aria-hidden className="size-3.5" /> : <RiArrowUpLine aria-hidden className="size-4" />}
              </button>
            </div>
          </div>
        </div>
        <div className="mx-auto mt-1.5 flex max-w-[680px] items-center gap-1 px-1">
          <StatusMenu
            label="Branch"
            icon={RiGitBranchLine}
            value={branch}
            display={branch}
            options={BRANCHES.map((b) => ({ id: b, label: b }))}
            onChange={onBranchChange}
          />
          <StatusMenu
            label="Project"
            icon={RiFolderLine}
            value={project}
            display={project}
            options={PROJECTS.map((p) => ({ id: p, label: p }))}
            onChange={onProjectChange}
          />
          <span className="flex-1" />
          <StatusMenu
            label="Mode"
            icon={ModeIcon}
            value={mode}
            display={MODES.find((m) => m.id === mode)?.label ?? "Agent"}
            options={MODES.map((m) => ({ id: m.id, label: m.label, hint: m.hint }))}
            onChange={onModeChange}
          />
          <ContextUsageRing
            used={contextUsed}
            limit={CONTEXT_LIMIT}
            size={16}
            breakdown={[
              { label: "System and tools", tokens: 21_000, tone: "purple" },
              { label: "Files read", tokens: Math.round((contextUsed - 21_000) * 0.6), tone: "blue" },
              { label: "Conversation", tokens: Math.round((contextUsed - 21_000) * 0.4), tone: "cyan" },
            ]}
          />
        </div>
      </div>

      <AlertDialog
        isOpen={confirmDelete}
        onOpenChange={setConfirmDelete}
        title="Delete this chat?"
        description={`"${thread.title}" and its messages will be removed. Uncommitted file changes stay in the panel.`}
        confirmLabel="Delete chat"
        onConfirm={onDelete}
      />
    </section>
  );
}

/** How long each agent step runs before the next one starts. */
export const STEP_MS = 1300;

